// Hand-written mirror of `purge.inventory/0` (crates/purge-model/src/inventory.rs). Temporary: in M3 these
// types are generated by NJsonSchema from the schemars output of purge-model (ENGINE_PLAN.md §3.3).
// Field names are snake_case on the wire; enums use the Rust variant names.

using System.Text.Json.Serialization;

namespace Purge.Client.Model;

/// <summary>The registry view an Uninstall key was read through.</summary>
[JsonConverter(typeof(JsonStringEnumConverter<RegistryView>))]
public enum RegistryView { K64, K32 }

/// <summary>The installer technology behind an entry.</summary>
[JsonConverter(typeof(JsonStringEnumConverter<InstallerKind>))]
public enum InstallerKind { Msi, Inno, Nsis, Burn, Unknown }

/// <summary>Machine-wide or for one user.</summary>
[JsonConverter(typeof(JsonStringEnumConverter<InstallScope>))]
public enum InstallScope { Machine, User }

/// <summary>Who can write the Uninstall key (lowercase on the wire).</summary>
[JsonConverter(typeof(JsonStringEnumConverter<WritableBy>))]
public enum WritableBy
{
    [JsonStringEnumMemberName("admin")] Admin,
    [JsonStringEnumMemberName("user")] User,
}

/// <summary>Where an install-time hint was read from.</summary>
[JsonConverter(typeof(JsonStringEnumConverter<InstallTimeSource>))]
public enum InstallTimeSource
{
    ArpInstallDate, KeyLastWrite, InstallDirCreation, UninstallLogCreation, MsiInstallDate,
}

/// <summary>The installation context of an MSI product.</summary>
[JsonConverter(typeof(JsonStringEnumConverter<MsiContext>))]
public enum MsiContext { Machine, UserManaged, UserUnmanaged }

public sealed record RawFlags(
    bool SystemComponent,
    bool HasDisplayName,
    bool HasUninstallString,
    string? ParentKey,
    string? ReleaseType,
    bool WindowsInstaller);

/// <summary>One raw install-time hint. <see cref="Time"/> is a Windows FILETIME (100 ns since 1601, UTC).</summary>
public sealed record InstallTimeEvidence(InstallTimeSource Source, ulong Time);

public sealed record MsiInfo(MsiContext Context, string? LocalPackage, string? InstallDate);

/// <summary>One installed program: one Uninstall key.</summary>
public sealed record InventoryEntry(
    string ProgramId,
    string KeyPath,
    string? HiveSid,
    RegistryView View,
    string DisplayName,
    string? Version,
    string? Publisher,
    RawFlags Flags,
    InstallerKind InstallerKind,
    InstallScope Scope,
    string? ProductCode,
    string? UpgradeCode,
    string? InnoAppId,
    WritableBy WritableBy,
    string? InstallLocation,
    string? UninstallString,
    string? QuietUninstallString,
    string? DisplayIcon,
    IReadOnlyList<InstallTimeEvidence>? InstallTimeEvidence,
    MsiInfo? Msi,
    bool Appx = false);

/// <summary>An MSI product without an Uninstall key.</summary>
public sealed record MsiOnlyRow(
    string ProductCode,
    MsiContext Context,
    string? UserSid,
    string? ProductName,
    string? Version,
    string? Publisher,
    string? InstallLocation,
    string? LocalPackage,
    string? InstallDate);

/// <summary>An inventory document; <see cref="Schema"/> is always <c>purge.inventory/0</c>.</summary>
public sealed record InventoryDoc(
    string Schema,
    IReadOnlyList<InventoryEntry> Entries,
    IReadOnlyList<MsiOnlyRow>? MsiOnly)
{
    public const string SchemaId = "purge.inventory/0";
}

/// <summary>Reply of <c>engine.hello</c> (ENGINE_PLAN.md §3.3).</summary>
public sealed record EngineHello(
    string Version,
    bool Elevated,
    string UserSid,
    string ShellSid,
    string Edition,
    string Build,
    bool BaselineAvailable,
    string PolicyVersion,
    string? BuildNote = null);

[JsonSourceGenerationOptions(PropertyNamingPolicy = JsonKnownNamingPolicy.SnakeCaseLower)]
[JsonSerializable(typeof(InventoryDoc))]
[JsonSerializable(typeof(EngineHello))]
[JsonSerializable(typeof(Dictionary<string, long>))]
[JsonSerializable(typeof(List<LeftoverForecast>))]
[JsonSerializable(typeof(QuarantineStatus))]
public sealed partial class PurgeJsonContext : JsonSerializerContext;
